exercises.solution:
const precoDigitado = '8,75';
const quilos = 2;

console.log(`Sem trocar a vírgula: ${Number(precoDigitado)}`);

const preco = Number(precoDigitado.replace(',', '.'));
const total = preco * quilos;
console.log(`Total: R$ ${total.toFixed(2)}`);

const notas = ['7.5', 'oito', '9', '6,5', '10'];

const invalidas = notas.filter((nota) => Number.isNaN(Number(nota)));
console.log(invalidas);

const validas = notas.filter((nota) => Number.isNaN(Number(nota)) === false);
const soma = validas.reduce((total, nota) => total + Number(nota), 0);
console.log(`Soma das válidas: ${soma}`);

